import pandas as pd,numpy as np
from scipy.optimize import least_squares
from scipy.signal import lfilter
def load(f):
    d=pd.read_csv(f)
    return dict(t=d.time_s.values,P=d.active_power_pu.values,Q=d.reactive_power_pu.values,V=d.voltage_pu.values,th=d.bus_angle_rad.values,S=d.voltage_setpoint_pu.values)
fl=['train/A_vref_op1.csv','train/A_vref_op3.csv']
D={f:load(f) for f in fl}
dt=0.001
def simQ(p,x,useP=True):
    Kp,Ki,Tm,Kpp=p
    V=x['V'];S=x['S'];P=x['P']
    a=np.exp(-dt/Tm)
    vm=lfilter([1-a],[1,-a],V-V[0])+V[0]
    e=(S-vm)-(S[0]-V[0])
    xi=np.concatenate([[0],np.cumsum(Ki*e[:-1]*dt)])
    return x['Q'][0]+Kp*e+xi+Kpp*(P-P[0])
def res(p):
    return np.concatenate([simQ(p,D[f])-D[f]['Q'] for f in fl])
